-- YT watch flow v3 (2026-10-08): scroll the description expander into view before clicking; live evidence showed a synthetic click on the below-fold control changed nothing
-- workflow that opens a URL and returns the transcript payload in one run,
-- so watching plus summarizing costs a single model round trip instead of a
-- hand-driven open/find/click/read chain. Adapted from the proven
-- youtube.get_transcript v5 fast path (panel probe, synthetic-then-trusted
-- open, render-ready activation with tab restore); v1 opened the tab from
-- input.url instead of requiring one, v2 adds a second 15s watch window
-- after a tolerated first miss (cold first render on a fresh tab).
--
-- No public MCP tool/schema, protocol, primitive, VM, signing, auth, or
-- transport boundary changes are introduced here.

select public.opera_register_workflow(
  'youtube.watch_summarize',
  $wf${"steps":[{"id":"open","type":"command","method":"tabs.open","params":{"url":{"$ref":"input.url"},"active":false,"wait":true}},{"name":"tabId","type":"set","value":{"$ref":"steps.open.result.tab.id"}},{"id":"watch","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-watch-flexy","timeoutMs":15000},"continueOnError":true},{"id":"watchAgain","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-watch-flexy","timeoutMs":15000}},{"name":"panelWasOpen","type":"set","value":false},{"name":"openMethod","type":"set","value":"none"},{"name":"activatedForRender","type":"set","value":false},{"id":"panel","type":"command","method":"page.query","params":{"index":0,"limit":5,"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-renderer, ytd-engagement-panel-section-list-renderer[target-id*=\"transcript\"][visibility=\"ENGAGEMENT_PANEL_VISIBILITY_EXPANDED\"]","visibleOnly":false},"continueOnError":true},{"else":[{"id":"transcript","type":"command","method":"page.find","params":{"text":"Show transcript","limit":5,"tabId":{"$ref":"vars.tabId"}},"continueOnError":true},{"else":[{"name":"transcriptRef","type":"set","value":{"$ref":"steps.transcript.result.item.ref"}}],"then":[{"id":"expand","type":"command","method":"page.query","params":{"index":0,"limit":5,"tabId":{"$ref":"vars.tabId"},"selector":"#description-inline-expander #expand, ytd-text-inline-expander #expand, tp-yt-paper-button#expand"},"continueOnError":true},{"else":[],"then":[{"id":"scrollexpand","type":"command","method":"page.scroll","params":{"ref":{"$ref":"steps.expand.result.item.ref"},"tabId":{"$ref":"vars.tabId"},"block":"center"},"continueOnError":true},{"id":"expandclick","type":"command","method":"page.click","params":{"ref":{"$ref":"steps.expand.result.item.ref"},"tabId":{"$ref":"vars.tabId"},"trusted":false},"continueOnError":true}],"type":"if","condition":{"op":"exists","left":{"$ref":"steps.expand.result.item"}}},{"id":"waittranscript","type":"command","method":"page.wait_for","params":{"text":"Show transcript","tabId":{"$ref":"vars.tabId"},"timeoutMs":5000}},{"name":"transcriptRef","type":"set","value":{"$ref":"steps.waittranscript.result.item.ref"}}],"type":"if","condition":{"op":"not_exists","left":{"$ref":"steps.transcript.result.item"}}},{"id":"openSynthetic","type":"command","method":"page.click","params":{"ref":{"$ref":"vars.transcriptRef"},"tabId":{"$ref":"vars.tabId"},"trusted":false},"continueOnError":true},{"id":"panelFast","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-renderer, ytd-engagement-panel-section-list-renderer[target-id*=\"transcript\"][visibility=\"ENGAGEMENT_PANEL_VISIBILITY_EXPANDED\"]","timeoutMs":1200,"visibleOnly":false},"continueOnError":true},{"else":[{"id":"transcriptFresh","type":"command","method":"page.find","params":{"text":"Show transcript","limit":5,"tabId":{"$ref":"vars.tabId"}}},{"id":"openTrusted","type":"command","method":"page.click","params":{"ref":{"$ref":"steps.transcriptFresh.result.item.ref"},"tabId":{"$ref":"vars.tabId"},"trusted":true}},{"id":"panelTrusted","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-renderer, ytd-engagement-panel-section-list-renderer[target-id*=\"transcript\"][visibility=\"ENGAGEMENT_PANEL_VISIBILITY_EXPANDED\"]","timeoutMs":8000,"visibleOnly":false}},{"name":"openMethod","type":"set","value":"trusted"}],"then":[{"name":"openMethod","type":"set","value":"synthetic"}],"type":"if","condition":{"op":"exists","left":{"$ref":"steps.panelFast.result.item"}}}],"then":[{"name":"panelWasOpen","type":"set","value":true},{"name":"openMethod","type":"set","value":"already-open"}],"type":"if","condition":{"op":"exists","left":{"$ref":"steps.panel.result.item"}}},{"id":"segmentFast","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","timeoutMs":1200,"visibleOnly":false},"continueOnError":true},{"else":[],"then":[{"id":"prevActive","type":"command","method":"tabs.get","params":{"tabId":{"$ref":"vars.tabId"}}},{"id":"activateForRender","type":"command","method":"tabs.activate","params":{"tabId":{"$ref":"vars.tabId"},"focusWindow":false}},{"name":"prevActiveId","type":"set","value":{"$ref":"steps.prevActive.result.tab.id"}},{"name":"activatedForRender","type":"set","value":true},{"id":"segmentReady","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","timeoutMs":6000,"visibleOnly":false}}],"type":"if","condition":{"op":"not_exists","left":{"$ref":"steps.segmentFast.result.item"}}},{"id":"segments","type":"command","method":"page.query","params":{"limit":100,"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","visibleOnly":false},"continueOnError":true},{"id":"segmentsAvailable","else":[{"name":"text","type":"set","value":""},{"name":"offset","type":"set","value":0},{"id":"chunks","type":"repeat","steps":[{"id":"read","type":"command","method":"page.read","params":{"limit":12000,"tabId":{"$ref":"vars.tabId"},"offset":{"$ref":"vars.offset"},"maxElements":1,"includeElements":false}},{"name":"text","type":"set","value":{"$concat":[{"$ref":"vars.text"},{"$ref":"steps.read.result.page.text"}]}},{"name":"offset","type":"set","value":{"$ref":"steps.read.result.page.nextOffset"}}],"until":{"op":"falsey","left":{"$ref":"steps.read.result.page.hasMore"}},"failOnLimit":false,"maxIterations":30}],"then":[],"type":"if","condition":{"op":"truthy","left":{"$ref":"steps.segments.result.count"}}},{"id":"tab","type":"command","method":"tabs.get","params":{"tabId":{"$ref":"vars.tabId"}}},{"else":[],"then":[{"else":[],"then":[{"id":"restoreActive","type":"command","method":"tabs.activate","params":{"tabId":{"$ref":"vars.prevActiveId"},"focusWindow":false},"continueOnError":true}],"type":"if","condition":{"op":"ne","left":{"$ref":"vars.prevActiveId"},"right":{"$ref":"vars.tabId"}}}],"type":"if","condition":{"op":"truthy","left":{"$ref":"vars.activatedForRender"}}}],"output":{"title":{"$ref":"steps.tab.result.tab.title"},"url":{"$ref":"steps.tab.result.tab.url"},"segments":{"$ref":"steps.segments.result.items"},"segmentCount":{"$ref":"steps.segments.result.count"},"text":{"$ref":"vars.text"},"openMethod":{"$ref":"vars.openMethod"},"panelWasOpen":{"$ref":"vars.panelWasOpen"},"activatedForRender":{"$ref":"vars.activatedForRender"}}}$wf$,
  'Open a YouTube URL in a background tab and return its transcript payload (segments with text, or page text fallback) plus title and open metadata, in one supervised run.',
  true
);
